  const { result } = renderHook(() => useSpringSequence([100, 200]));
  expect(result.current.values).toEqual([0, 0]);
});

test('isRunning is false initially', () => {
  const { result } = renderHook(() => useSpringSequence([50]));
  expect(result.current.isRunning).toBe(false);
});

test('start sets isRunning to true', () => {
  const { result } = renderHook(() => useSpringSequence([100]));
  act(() => result.current.start());
  expect(result.current.isRunning).toBe(true);
});

test('reset returns values to 0 and stops animation', () => {
  const { result } = renderHook(() => useSpringSequence([100, 200]));
  act(() => result.current.start());
  act(() => result.current.reset());
  expect(result.current.values).toEqual([0, 0]);
  expect(result.current.isRunning).toBe(false);
});

