import { useState, useCallback, useRef, useEffect } from 'react';

type SpringConfig = { stiffness?: number; damping?: number };

export function useSpringSequence(
  targets: number[],
  config: SpringConfig = {}
) {
  const { stiffness = 170, damping = 26 } = config;
  const [values, setValues] = useState(() => targets.map(() => 0));
  const [isRunning, setIsRunning] = useState(false);
  const rafRef = useRef<number | null>(null);
  const velocities = useRef(targets.map(() => 0));
  const positions = useRef(targets.map(() => 0));
  const running = useRef(false);

  const animate = useCallback(() => {
    let allSettled = true;
    for (let i = 0; i < targets.length; i++) {
      const force = stiffness * (targets[i] - positions.current[i]);
      const damper = damping * velocities.current[i];
      velocities.current[i] += (force - damper) / 60;
      positions.current[i] += velocities.current[i];
      if (Math.abs(targets[i] - positions.current[i]) > 0.1) allSettled = false;
    }
    setValues([...positions.current]);
    if (!allSettled && running.current) {
      rafRef.current = requestAnimationFrame(animate);
    } else {
      running.current = false;
      setIsRunning(false);
    }
  }, [targets, stiffness, damping]);

  const start = useCallback(() => {
    running.current = true;
    setIsRunning(true);
    rafRef.current = requestAnimationFrame(animate);
  }, [animate]);

  const reset = useCallback(() => {
    running.current = false;
    if (rafRef.current) cancelAnimationFrame(rafRef.current);
    velocities.current = targets.map(() => 0);
    positions.current = targets.map(() => 0);
    setValues(targets.map(() => 0));
    setIsRunning(false);
  }, [targets]);

  useEffect(() => () => { if (rafRef.current) cancelAnimationFrame(rafRef.current); }, []);

  return { values, start, reset, isRunning };
}
